// Block (composition) — a floating control bar pinned to the bottom of the viewport.
// Contract: docs/rules/block-contract.md. This is the three-tier split §6 (surface ownership)
// asks for, and the reason Toolbar carries no chrome of its own:
//   Toolbar → BEHAVIOUR (role="toolbar", roving focus, orientation)
//   Card    → SURFACE   (size="small" variant="raised" — compact inset + the floating elevation)
//   Block   → PLACEMENT (position: fixed on the sticky layer — the half only a Block can supply)
// Same shape as BottomNav; that one is a `<nav>` landmark of destinations, this one is a
// `role="toolbar"` group of actions on the current view (selection actions, an editor's format
// bar). The Block owns no look and mints no tokens — its CSS only pins the bar.
// Posture: self-contained floating chrome.
// Centres on the VIEWPORT by default. A consumer whose canvas is one region of the page — an
// editor pane, a preview column — passes that region's inline insets as `insetInline` and the bar
// centres there instead, still pinned to the bottom of the screen.
import type { CSSProperties, ReactNode, Ref } from "react";
import { Card } from "../components/Card";
import { Toolbar } from "../components/Toolbar";
import { useScrollClearance } from "../components/useScrollClearance";
import "./FloatingToolbar.css";

export interface FloatingToolbarProps {
  /** The controls — Buttons, ToggleButtonGroups, and `ToolbarSeparator`s between groups.
   *  Toolbar action buttons are conventionally `ghost`, so the Card's surface shows through. */
  children?: ReactNode;
  /** Accessible name for the toolbar. Required: a `role="toolbar"` has no visible label of its
   *  own (WAI-ARIA toolbar pattern) — the same reason Toolbar itself demands one. */
  "aria-label": string;
  /** The horizontal span the bar centres within, as CSS inline insets (`"600px 24px"`). Omit for
   *  the viewport, which is what every consumer wants until its canvas is one region of the page.
   *  A prop rather than a bare custom property because the CSS declares that property `initial`,
   *  which resets inheritance — so the Block sets it or nothing does. */
  insetInline?: string;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function FloatingToolbar({
  children,
  "aria-label": ariaLabel,
  insetInline,
  className,
  ref,
}: FloatingToolbarProps) {
  // The bar covers the bottom of the page, so the document keeps focus clear of it (WCAG 2.4.11).
  const clearRef = useScrollClearance("end", ref);
  return (
    <div
      ref={clearRef}
      style={
        insetInline
          ? ({ "--sd-layout-floating-toolbar-inline": insetInline } as CSSProperties)
          : undefined
      }
      className={className ? `sd-floatingtoolbar ${className}` : "sd-floatingtoolbar"}
    >
      {/* `raised` because the bar genuinely floats over page content; `small` keeps it compact
          rather than the roomier card tier. */}
      <Card size="small" variant="raised" className="sd-floatingtoolbar__bar">
        {/* No layout wrapper needed: the Toolbar is a single child of the Card's column, and it
            lays its OWN controls out in a row. (Measured — adding a row Stack changed nothing.)
            The controls do need `ToolbarSeparator orientation="vertical"`: a divider runs
            perpendicular to the bar, and RAC's Separator defaults to horizontal, which renders a
            full-width rule that wraps every control onto its own line. */}
        <Toolbar aria-label={ariaLabel}>{children}</Toolbar>
      </Card>
    </div>
  );
}

/* FloatingToolbar.css — .sd-floatingtoolbar (Block)
   Arrangement only: pin the bar to the bottom-center of the viewport. All look (surface, radius,
   shadow) is owned by the composed Card (size=small variant=raised); the controls' look by Button /
   ToggleButtonGroup. References Sys layout scales only; defines no tokens. */
.sd-floatingtoolbar {
  position: fixed;
  /* The horizontal SPAN the bar centres within, as inline insets. `0` is the viewport, which is
     the default.
     It is a seam rather than a prop because centring over a REGION is the same placement with
     different bounds, not a second behaviour: `justify-content: center` below does the work either
     way. A `--sd-layout-*` local intermediate is the shape block-contract.md §4b names for exactly
     this — set inline by the consumer, never a token, never in tokens.css.
     `fixed` stays: a consumer whose region scrolls with the page needs the bar to stay on screen,
     and `absolute` would pin it to the region's bottom and carry it out of view. Measured in the
     theme studio, whose page is 2249px in a 1000px viewport with no scrollport around the preview. */
  /* Declared, not merely referenced. `token-tier:check` flags an undeclared var even when it
     carries a fallback, and the reason is the house convention: the declaration doubles as this
     file's manifest of its own local intermediates, so a typo cannot hide behind a fallback. The
     same shape Stack.css uses for every `--sd-layout-*`.
     `initial` also settles HOW the value arrives: it resets inheritance, so the variable cannot be
     set from an ancestor — it comes through the `insetInline` prop, which is the typed seam rather
     than a contract a consumer has to know about. */
  --sd-layout-floating-toolbar-inline: initial;
  inset-inline: var(--sd-layout-floating-toolbar-inline, 0);
  inset-block-end: var(--sd-overlay-margin-medium);
  display: flex;
  justify-content: center;
  z-index: var(--sd-layer-sticky);
  /* Let clicks fall through the transparent gutter beside the bar; the bar itself re-enables
     hit-testing below. Without this the invisible full-width strip would swallow every click
     along the bottom of the page. */
  pointer-events: none;
}

.sd-floatingtoolbar__bar {
  pointer-events: auto;
  /* Hug the controls rather than stretch across the flex line — the bar is as wide as what it
     holds, and `justify-content: center` above then centres it. */
  width: max-content;
  /* Never wider than the viewport gutter allows. Toolbar already sets `flex-wrap: wrap`, so a
     control set that outgrows this cap wraps onto a second line inside the bar rather than
     running off-screen — no scroller needed, and wrapping keeps every control reachable by
     pointer (a horizontal scroller inside a fixed bar is easy to miss). */
  max-width: calc(100% - 2 * var(--sd-overlay-margin-medium));
}
